(function(){
  const style=document.createElement('style');style.textContent='.aod-modal{position:fixed;inset:0;z-index:12000;background:#10251b88;display:none;align-items:center;justify-content:center;padding:20px;direction:rtl;font-family:Cairo,Arial}.aod-modal.show{display:flex}.aod-card{width:min(760px,100%);max-height:88vh;overflow:auto;background:#fff;border-radius:18px;padding:22px}.aod-row{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.aod-close{border:0;border-radius:9px;background:#eef4f1;color:#164b39;padding:9px 13px;font-weight:800}.aod-summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:9px;margin:15px 0}.aod-summary div,.aod-item,.aod-event{border:1px solid #dce7e1;border-radius:10px;padding:11px}.aod-summary small,.aod-event small{display:block;color:#718078;font-size:11px}.aod-list{display:grid;gap:8px}.aod-event{border-right:4px solid #157a5b}.aod-error{color:#b42318}';document.head.appendChild(style);
  document.body.insertAdjacentHTML('beforeend','<section id="aodModal" class="aod-modal"><div class="aod-card"><div class="aod-row"><h2 id="aodTitle">تفاصيل الطلب</h2><button id="aodClose" class="aod-close">إغلاق</button></div><div id="aodBody">جارٍ التحميل…</div></div></section>');
  const $=id=>document.getElementById(id),statusText={awaiting_merchant:'إنشاء الطلب وانتظار المحل',preparing:'قبول المحل وبدء التجهيز',awaiting_rider:'جاهز وبانتظار المندوب',assigned:'قبول المندوب',picked_up:'استلام المندوب للطلب',delivered:'تسليم الطلب',cancelled:'إلغاء الطلب'};
  function element(tag,text,className){const node=document.createElement(tag);node.textContent=String(text??'');if(className)node.className=className;return node}
  async function open(code){const modal=$('aodModal'),body=$('aodBody');modal.classList.add('show');body.textContent='جارٍ التحميل…';try{const token=localStorage.getItem('khalasaStaffToken')||'',base=window.KHALASA_API_BASE_URL||location.origin,response=await fetch(`${base}/v1/admin/order-details/${encodeURIComponent(code)}`,{headers:{Authorization:`Bearer ${token}`}}),data=await response.json();if(!response.ok)throw new Error(data.error||'FAILED');body.replaceChildren();$('aodTitle').textContent=`تفاصيل ${data.order.public_code}`;const summary=document.createElement('div');summary.className='aod-summary';for(const [label,value] of [['العميل',data.order.customer_name],['المحل',data.order.merchant_name],['المندوب',data.order.rider_name||'لم يُعيّن'],['الحالة',statusText[data.order.status]||data.order.status],['العنوان',data.order.delivery_address],['الإجمالي',`${Number(data.order.merchandise_total)+Number(data.order.delivery_fee)} ج.م`]]){const box=document.createElement('div');box.append(element('small',label),element('b',value));summary.append(box)}body.append(summary,element('h3','المواد'));const items=document.createElement('div');items.className='aod-list';for(const item of data.items||[])items.append(element('div',`${item.product_name} × ${item.quantity} — ${Number(item.unit_price)*Number(item.quantity)} ج.م`,'aod-item'));body.append(items,element('h3','السجل الزمني'));const events=document.createElement('div');events.className='aod-list';for(const event of data.events||[]){const row=document.createElement('div');row.className='aod-event';row.append(element('b',statusText[event.status]||event.status),element('p',event.note||''),element('small',`${new Date(event.created_at).toLocaleString('ar-EG')} · ${event.actor_name||'النظام'}`));events.append(row)}body.append(events)}catch(_){body.replaceChildren(element('p','تعذر تحميل تفاصيل الطلب.','aod-error'))}}
  document.addEventListener('click',event=>{const button=event.target.closest('.admin-order .table-btn');if(!button)return;event.preventDefault();event.stopImmediatePropagation();const heading=button.closest('.admin-order')?.querySelector('h3')?.textContent||'',code=heading.split('·')[0].trim();if(code)open(code)},true);
  $('aodClose').onclick=()=>$('aodModal').classList.remove('show');
})();
